  });

  window.addEventListener(&#39;message&#39;, (event) =&gt; {
    if (event.data &amp;&amp; event.data.type === &#39;lightboxBackButtonVisibilityChange&#39;) {
      const backBtn = document.getElementById(&#39;lightbox-back-arrow&#39;);
